package com.gitlab.secondstarcavalier.controlplane.services.kernel.tacplus.utils;

import java.util.Base64;

import com.gitlab.secondstarcavalier.controlplane.services.kernel.tacplus.types.libs.errors.ProtoException;

import io.grpc.Status;
import io.grpc.StatusRuntimeException;

/**
 * Utils provides shared utility methods for base64 decoding and gRPC-to-HTTP
 * status code mapping. Mirrors Go's utils/utils.go for cross-language parity.
 *
 * Generated by tacplus
 */
public final class Utils {
    private Utils() {} // Prevent instantiation

    /**
     * Decodes a base64-encoded string, automatically detecting the encoding variant.
     * Tries URL-safe, then standard encoding, with and without padding.
     *
     * @param input The base64-encoded string
     * @return The decoded bytes
     * @throws ProtoException if all decoding variants fail
     */
    public static byte[] decodeBase64(String input) throws ProtoException {
        // Try URL-safe without padding
        try {
            return Base64.getUrlDecoder().decode(input);
        } catch (IllegalArgumentException ignored) {}

        // Try standard without padding
        try {
            return Base64.getDecoder().decode(input);
        } catch (IllegalArgumentException ignored) {}

        // Try URL-safe with padding
        try {
            return Base64.getUrlDecoder().decode(padBase64(input));
        } catch (IllegalArgumentException ignored) {}

        // Try standard with padding
        try {
            return Base64.getDecoder().decode(padBase64(input));
        } catch (IllegalArgumentException ignored) {}

        throw ProtoException.newErrMissingInvalidData(null, "failed to decode base64 string");
    }

    private static String padBase64(String input) {
        int pad = (4 - input.length() % 4) % 4;
        return input + "=".repeat(pad);
    }

    /**
     * Maps a gRPC status code to an HTTP status code.
     *
     * @param code The gRPC status code
     * @return The corresponding HTTP status code
     */
    public static int grpcStatusToHttp(Status.Code code) {
        if (code == null) {
            return 500;
        }
        return switch (code) {
            case OK -> 200;
            case INVALID_ARGUMENT -> 400;
            case UNAUTHENTICATED -> 401;
            case PERMISSION_DENIED -> 403;
            case NOT_FOUND -> 404;
            case ALREADY_EXISTS -> 409;
            case RESOURCE_EXHAUSTED -> 429;
            case FAILED_PRECONDITION -> 400;
            case UNIMPLEMENTED -> 501;
            case UNAVAILABLE -> 503;
            case DEADLINE_EXCEEDED -> 504;
            default -> 500;
        };
    }

    /**
     * Extracts the gRPC status code from a Throwable and maps it to an HTTP status code.
     * Returns 200 if the error is null, 500 if the error is not a gRPC StatusRuntimeException.
     *
     * @param err The error (may be null)
     * @return The corresponding HTTP status code
     */
    public static int grpcStatusToHttp(Throwable err) {
        if (err == null) {
            return 200;
        }
        if (err instanceof StatusRuntimeException sre) {
            return grpcStatusToHttp(sre.getStatus().getCode());
        }
        return 500;
    }
}
